            adj.setdefault(a, []).append(b)

    # BFS
    from collections import deque
    q = deque([(src, 0)])
    visited = {src}

    while q:
        node, dist = q.popleft()
        for nxt in adj.get(node, []):
            if nxt == dst:
                return dist + 1
            if nxt not in visited:
                visited.add(nxt)
                q.append((nxt, dist + 1))

    return None

