            if stack and stack[-1] != '..':
                stack.pop()
            else:
                stack.append('..')
        else:
            # ordinary component: make it lowercase
            stack.append(part.lower())
    return stack

def solve(record):
    """
    Normalizes a slash‑separated relative path taken from record['record_1'].
    Returns a list of path components after:
      - ignoring empty components caused by repeated slashes,
      - keeping every '.' component as a literal,
      - keeping component case unchanged,
      - removing a preceding normal component for each '..' when possible,
      - preserving any excess '..' that cannot be removed.
    """
    try:
        x = record['record_1']
    except Exception:
        return []
    if not isinstance(x, str):
        return []

    components = x.split('/')
    stack = []
    for comp in components:
        if comp == '':
            # empty piece from // or leading/trailing slash
            continue
        if comp == '.':
            stack.append('.')
        elif comp == '..':
            # try to cancel the closest preceding normal component
            for i in range(len(stack) - 1, -1, -1):
                if stack[i] not in ('.', '..'):
                    del stack[i]
                    break
            else:
                # no normal component to cancel -> keep the '..'
                stack.append('..')
        else:
            stack.append(comp)
    return stack
